"""Independently authored purpose, procedure and return values for every sketch function."""
DOCS = {
'set_RightMotor': ('右モーターの回転方向を設定する。', '1. isDir1Highを右方向端子D12へdigitalWriteで出力する。\n2. isDir2Highを右方向端子D11へ出力する。PWM値は変更しない。'),
'set_LeftMotor': ('左モーターの回転方向を設定する。', '1. isDir1Highを左方向端子D7へdigitalWriteで出力する。\n2. isDir2Highを左方向端子D8へ出力する。PWM値は変更しない。'),
'set_MotorSpeed': ('左右の車輪の駆動強度を指定する。', '1. rightSpeedを右PWM端子D9へanalogWriteで出力する。\n2. leftSpeedを左PWM端子D6へ出力する。方向端子は変更せず、値の範囲は呼び出し側で0〜255に収める。'),
'go_Advance': ('車体をまっすぐ前進させる。', '1. 右・左とも方向端子をHIGH/LOWに設定する。\n2. set_MotorSpeed(SPEED, SPEED)を呼び、両輪へPWM100を出力する。'),
'go_Back': ('リモコンの後退指示に対応する駆動を行う。', '1. 右・左とも方向端子をLOW/HIGHに設定する。\n2. 両輪へSPEED=100のPWMを出力する。この関数は手動のGO_BACK出力に使用し、障害物回避から自動選択しない。'),
'go_Left': ('その場で左向きに旋回させる。', '1. 右輪をHIGH/LOW、左輪をLOW/HIGHに設定し、互いに逆方向へ駆動する。\n2. isDancingに応じて両輪のPWMをDANCE_SPEED=180またはSPEED=100にする。'),
'go_Right': ('その場で右向きに旋回させる。', '1. 右輪をLOW/HIGH、左輪をHIGH/LOWに設定し、互いに逆方向へ駆動する。\n2. isDancingが真なら両輪PWM180、偽なら両輪PWM100を出力する。'),
'go_ForwardLeft': ('前進しながら左へカーブさせる。', '1. 右・左とも方向端子をHIGH/LOWにそろえる。\n2. 外側の右輪へDIAGONAL_OUTER_SPEED=220、内側の左輪へDIAGONAL_INNER_SPEED=60を出力する。'),
'go_ForwardRight': ('前進しながら強めに右へカーブさせる。', '1. 右・左とも方向端子をHIGH/LOWにそろえる。\n2. 内側の右輪へRIGHT_CURVE_INNER_SPEED=40、外側の左輪へRIGHT_CURVE_OUTER_SPEED=245を出力する。'),
'go_BackLeft': ('後退しながら左へカーブさせる。', '1. 右・左とも方向端子をLOW/HIGHにそろえる。\n2. 右輪へDIAGONAL_INNER_SPEED=60、左輪へDIAGONAL_OUTER_SPEED=220を出力する。'),
'go_BackRight': ('後退しながら強めに右へカーブさせる。', '1. 右・左とも方向端子をLOW/HIGHにそろえる。\n2. 右輪へRIGHT_CURVE_OUTER_SPEED=245、左輪へRIGHT_CURVE_INNER_SPEED=40を出力する。'),
'go_Stop': ('モーターへの駆動出力を停止する。', '1. set_MotorSpeed(0, 0)で左右のPWMを0にする。\n2. 右・左の方向端子をそれぞれLOW/LOWにする。空転停止のため、車輪が静止するまでの時間は実機に依存する。'),
'do_Drive_Tick': ('現在の走行状態をモーター出力へ反映する。', '1. Drive_Numをswitchで判定する。\n2. 前進・後退・左右旋回・4種類のカーブ・停止に対応するgo_関数を1つ呼ぶ。\n3. 定義外の状態ならDrive_NumをGO_STOPへ補正してgo_Stopを呼ぶ。'),
'warning': ('警告音の再生開始を受け付ける。', '1. millisで現在時刻を取得し、警告中または前回開始から1000ms未満なら処理を終える。\n2. 初回済みフラグ、開始時刻、フェーズと波形の初期状態を記録する。\n3. D13をHIGHにし、実際の発音更新をdo_Warning_Tickに引き継ぐ。初回は時刻0でも受け付ける。'),
'do_Warning_Tick': ('警告の音と無音を時間に従って切り替える。', '1. 警告中でなければ終了する。開始から200ms以上なら消音し、音楽のnoteStartMsに中断時間を加えて波形状態を戻す。\n2. 経過時間を50msで割ってフェーズを求め、奇数フェーズではD13をHIGHにする。\n3. 偶数フェーズでは250μs以上の間隔でD13のLOW/HIGHを1回切り替え、2kHzを目標とする波形を出す。'),
'play_Tone': ('1音分の発音条件を準備する。', '1. msが正ならtoneDurationMsへ保存し、0以下なら0にする。\n2. freqが正なら500000/freqをhalfPeriodUsへ保存し、0以下なら休符として0にする。\n3. 波形の時刻と位相を初期化し、警告中でなければD13をHIGHにする。ここでは発音時間を待たない。'),
'get_SongNote': ('指定位置の音の高さを取得する。', '1. notePtrが指すPROGMEM上の16bit値をpgm_read_wordで読む。\n2. 読んだ値をint16_tとして解釈して返す。通常は周波数、終端ではEND_MARK=-1になる。'),
'get_SongLength': ('指定音符の長さ係数を取得する。', '1. notePtrから1要素進め、音符ペアの長さ側の16bit値をPROGMEMから読む。\n2. int16_tとして解釈した係数を返す。ミリ秒への換算はplay_Noteで行う。'),
'play_Note': ('次に鳴らす音符をスケジュールする。', '1. get_SongLengthの係数にTEMPO_MS=150を掛け、noteDurationMsへ保存する。\n2. noteStartMsへ現在時刻を記録する。\n3. 全長から末尾の20msを差し引いた発音時間を求める。全長20ms以下なら0とする。\n4. get_SongNoteで高さを読み、play_Toneへ高さと発音時間を渡す。'),
'stop_Music': ('音の再生と予約をまとめて取り消す。', '1. 通常再生・ダンス曲・警告のフラグを解除する。\n2. currentNotePtrをnullptr、pendingSongNumとhalfPeriodUsを0にする。\n3. D13をHIGHにして消音する。Drive_Numやモーター出力には触れない。'),
'play_Music': ('指定番号の通常曲へ切り替える。', '1. songNumが1〜9の範囲外なら何もせず終了する。\n2. ダンス曲フラグを解除し、SONG_TABLEからpgm_read_ptrで曲の先頭を取得する。\n3. 再生フラグを有効にしてplay_Noteで最初の音符を設定する。走行状態は変更しない。'),
'is_MusicDue': ('予約した曲の再生開始時期を判定する。', '1. pendingSongNumが0でなく、予約が存在するか確認する。\n2. millisとpendingSongMsの差がCONFLICT_MS=300以上か調べ、両条件の論理積を返す。'),
'do_Music_Tick': ('曲の進行とブザー波形を1周期分更新する。', '1. do_Warning_Tickを呼び、警告が継続中なら音楽側の更新を終える。\n2. 曲予約の期限が来ていれば予約を取り出してplay_Musicで切り替える。未再生または音符ポインタが空なら終了する。\n3. 音符の全長を過ぎたら次のペアへ進む。終端でダンス専用曲なら先頭に戻し、通常曲なら次曲予約を残して再生を終了する。\n4. 切替時はplay_Noteで新しい音符を設定する。休符または発音時間を過ぎた音符はHIGHで消音する。\n5. 半周期以上たっているときだけ波形を1回切り替える。待機ループは使用しない。'),
'watch': ('超音波から前方までの距離を測る。', '1. TrigのD10をLOWで2μs、HIGHで10μs、その後LOWにする。\n2. pulseInでD3のHIGHパルス幅を最大25000μs待って取得する。\n3. 幅が0なら999を返し、それ以外は幅を58で割った整数cmを返す。故障と遠方は区別しない。'),
'is_FrontBlocked': ('前方障害物の検知を再確認する。', '1. watchで距離を測り、DISTANCE_LIMIT=20cmを超えていればfalseを返す。\n2. 20cm以下ならdelay(30)で待ち、もう一度watchを実行する。\n3. 2回目も20cm以下ならtrueを返す。測定と再確認待機の間は他の周期処理も遅れる。'),
'is_BackIrOn': ('後方センサーの現在の検知状態を読む。', '1. 左後方D0を読み、LOWなら検知ありとする。\n2. D0がLOWでない場合は右後方D2を読む。少なくとも片方がLOWならtrue、それ以外はfalseを返す。'),
'is_BackBlocked': ('後方障害物の検知を再確認する。', '1. is_BackIrOnで検知がなければfalseを返す。\n2. 検知があればdelay(20)で待ち、もう一度is_BackIrOnを呼ぶ。\n3. 再確認でも検知していればtrueを返す。'),
'start_Avoid': ('許可された自動回避動作を開始する。', '1. actがGO_ADVANCEでもGO_RIGHTでもなければend_Avoidで停止して終了する。\n2. Drive_Numをact、lastDriveCmdをGO_STOPにし、do_Drive_Tickで駆動する。\n3. isAvoidingを有効にして、駆動直後の時刻をavoidStartMsへ記録する。\n4. warningで警告を開始する。通常曲と曲予約は保持する。'),
'end_Avoid': ('自動回避を終了して停止状態へ戻す。', '1. isAvoidingをfalse、Drive_NumをGO_STOPにする。\n2. go_StopでPWMと方向端子を停止値へ変更する。'),
'update_Avoid': ('回避動作を続けるか終了するか判断する。', '1. avoidStartMsから500ms以上たっていればend_Avoidを呼んで終了する。\n2. 前進回避のときだけis_FrontBlockedで進行先を確認する。右旋回ではこのセンサー確認を行わない。\n3. 前方検知、または測定後の500ms経過でend_Avoidを呼ぶ。それ以外は回避状態を維持する。'),
'is_CheckTime': ('通常走行のセンサー確認要否を判定する。', '1. Drive_Numが前進・後退とそれらの4カーブ以外ならfalseを返す。\n2. 新規確認要求があるか、lastCheckMsから100ms以上経過していればtrueを返す。'),
'mark_Checked': ('センサー確認の実施時刻を記録する。', '1. isCheckRequestedをfalseにし、新しい指示に伴う即時確認要求を解除する。\n2. millisをlastCheckMsへ保存する。呼び出し位置は測定の開始前なので、記録するのは開始側の時刻になる。'),
'update_ObstacleFlags': ('前後の検知結果を共有状態へ反映する。', '1. is_FrontBlockedの結果を、検知なら1、未検知なら0としてfrontへ保存する。\n2. 続いてis_BackBlockedを呼び、同じ規則でbackを更新する。'),
'decide_AvoidAction': ('障害物に対して停止または回避方向を選ぶ。', '1. Drive_Numが前進系か後退系かを判定する。\n2. 前進系でfrontが真なら、backの値に関係なくGO_STOPを返す。\n3. 後退系でbackが真なら、frontも真のときGO_RIGHT、そうでなければGO_ADVANCEを返す。\n4. その他はDEFを返す。GO_BACKを自動回避として返す経路はない。'),
'checkSensorsAndObstacles': ('走行に優先する障害物対応を実行する。', '1. 回避中ならupdate_Avoidだけを呼んで戻り、ダンス中なら通常の確認を省く。\n2. is_CheckTimeがfalseなら戻る。確認が必要ならmark_Checked、update_ObstacleFlags、decide_AvoidActionの順に呼ぶ。\n3. 判断がGO_STOPならend_Avoidで即停止し、lastDriveCmdをGO_STOPへ戻してwarningを呼ぶ。\n4. DEF以外の残る回避指示はstart_Avoidへ渡す。DEFなら現在の走行を維持する。'),
'stop_Dance': ('ダンスと専用曲の継続を解除する。', '1. isDancingをfalse、Drive_NumをGO_STOPにし、go_Stopを呼ぶ。\n2. isDanceMusicが真の場合だけstop_Musicを呼ぶ。通常曲の再生状態はこの条件に入らなければ変更しない。'),
'dance_Action': ('指定ステップで使う走行状態を選ぶ。', '1. stepをswitchで比較し、0/4ならGO_RIGHT、2/6ならGO_LEFTを返す。\n2. 1/3/5/7および範囲外はGO_STOPを返す。旋回時間そのものはdance_Durationで決める。'),
'dance_Duration': ('指定ステップの継続時間を取得する。', '1. stepが0/2なら650ms、1/3/5なら180msを選ぶ。\n2. 4なら右一回転用DANCE_SPIN_MS=2000ms、6なら左一回転用DANCE_LEFT_SPIN_MS=2000msを選ぶ。\n3. 7と範囲外は350msを返す。左右の一回転時間は実機に合わせて別々に調整する。'),
'start_Dance': ('ダンス動作と専用曲を先頭から起動する。', '1. isAvoidingが真なら何もせず戻る。\n2. ダンスを有効にし、ステップ0とその開始時刻、初回センサー確認用の値を設定する。\n3. lastDriveCmdと曲予約を解除し、ダンス曲・音楽再生のフラグを有効にする。\n4. currentNotePtrをDANCE_SONGへ設定してplay_Noteを呼び、Drive_Numに最初の動作を設定する。モーター出力は次の安全確認後に行う。'),
'do_Dance_Tick': ('ダンスの安全確認とステップ進行を行う。', '1. isDancingがfalseなら戻る。初回または前回確認から100ms以上なら前後センサーを確認する。\n2. どちらかが検知したらstop_Danceを呼び、動きと専用曲を止める。\n3. dance_Durationで決まる時間がまだ経過していなければ戻る。\n4. 次のステップへ進め、8になったら0へ戻す。開始時刻とDrive_Numを更新する。曲のループはdo_Music_Tickが別途行う。'),
'is_OppositeDrive': ('2つの単独方向が反対向きか調べる。', '1. a/bが前進と後退の組合せか、左と右の組合せかを比較する。\n2. どちらの入力順でも一致すればtrue、それ以外はfalseを返す。'),
'get_DiagonalDrive': ('上下と左右の入力をカーブ状態へ変換する。', '1. a/bについて、前進と左・前進と右・後退と左・後退と右の4組を、順序を入れ替えた場合も含めて比較する。\n2. 一致した組の前左・前右・後左・後右を返し、組合せがなければDEFを返す。'),
'is_DiagonalComponent': ('単独方向が現在のカーブに含まれるか調べる。', '1. diagonalが4種類のカーブのどれに当たるかを分岐する。\n2. そのカーブを構成する上下または左右の方向とcmdが一致すればtrueを返す。カーブでない場合や不一致はfalseになる。'),
'set_Drive': ('方向入力を現在の走行指示へ組み込む。', '1. 現在時刻と直前入力からの経過時間を求める。\n2. 直前の単独入力と300ms以内で逆方向なら、現在と直前の走行をGO_STOPにし、時刻と確認要求を更新して戻る。\n3. その他は現在のDrive_Numとcmdをget_DiagonalDriveへ渡す。カーブの構成方向の再入力、または組合せなしならcmdを単独採用し、それ以外は得られたカーブを採用する。\n4. lastDriveCmd、入力時刻、isCheckRequestedを更新する。カーブ合成の入力間隔に制限は設けない。'),
'read_IR_Command': ('新しいリモコンの受信コードを取り出す。', '1. decodeで受信がなければNO_COMMANDを返す。\n2. 受信データからcommandとリピートフラグを読み、resumeで次の受信を許可する。\n3. リピートならNO_COMMAND、それ以外なら取得したcommandを返す。'),
'handle_StopButton': ('OKによる全体停止の状態を設定する。', '1. isAvoidingとisDancingをfalseにする。\n2. stop_Musicで通常曲・専用曲・曲予約・警告を解除して消音する。\n3. Drive_NumとlastDriveCmdをGO_STOPにする。モーター停止値は同じloopのdo_Drive_Tickで出力する。'),
'handle_DriveButton': ('矢印コードを単独方向の指示へ対応させる。', '1. commandを24/82/8/90と比較し、前進/後退/左/右のDriveStateを選ぶ。\n2. 一致した場合だけset_Driveへ渡す。その他のコードでは走行状態を更新しない。'),
'get_SongNum': ('数字コードから通常曲の番号を求める。', '1. NUM_CODESを先頭からSONG_COUNT=9件まで順に比較する。\n2. commandと一致した添字に1を足して返す。最後まで一致しなければ0を返す。'),
'is_NumberConflict': ('新しい曲指定が未確定の予約と競合するか調べる。', '1. pendingSongNumが0でないことと、songNumがその予約番号と異なることを確認する。\n2. さらに予約からの経過が300ms未満ならtrue、それ以外はfalseを返す。'),
'handle_NumberButton': ('数字入力に応じて曲の予約を管理する。', '1. get_SongNumで曲番号を求め、0なら何もせず戻る。\n2. 300ms未満の別番号との競合なら予約番号を0にして戻る。\n3. 同じ番号の300ms未満の再入力なら、最初の予約時刻を保ったまま戻る。\n4. その他は最新の曲番号と現在時刻を予約として保存する。'),
'do_IR_Tick': ('リモコン入力を優先順位に従って振り分ける。', '1. read_IR_Commandを1回呼び、NO_COMMANDなら戻る。\n2. OKならhandle_StopButtonを実行する。OK以外で回避中なら入力を無視する。\n3. 0ならstart_Danceで開始・再開する。それ以外でダンス中なら入力を無視する。\n4. 通常時はhandle_DriveButton、handle_NumberButtonの順に渡す。'),
'init_MotorPins': ('モーター端子を停止状態で使い始める。', '1. PWMのD9/D6と方向のD12/D11/D7/D8をOUTPUTへ設定する。\n2. go_Stopを呼び、初期出力をPWM0・方向LOWにする。'),
'init_BuzzerPin': ('ブザー端子の初期出力を消音にそろえる。', '1. D13へHIGHを設定してからOUTPUTへ切り替える。\n2. もう一度HIGHを出力する。setup実行前のブートローダーによる出力はこの関数で制御しない。'),
'init_SensorPins': ('前後の検知に使う端子を準備する。', '1. 超音波のTrig D10をOUTPUT、Echo D3をINPUTにする。\n2. 後方赤外線のD0/D2をINPUTにする。ここでは距離測定や障害物判定は行わない。'),
'init_IrReceiver': ('赤外線リモコンの受信を有効にする。', '1. IrReceiver.beginへIR_RECEIVE_PIN=D4を渡す。\n2. DISABLE_LED_FEEDBACKを指定し、ブザーと共有するD13を受信LEDで点滅させない。'),
'setup': ('起動時に各機器を初期化する。', '1. init_MotorPinsでモーター端子と停止出力を設定する。\n2. init_BuzzerPin、init_SensorPins、init_IrReceiverの順に呼ぶ。'),
'loop': ('入力・判断・出力を周期的に実行する。', '1. do_IR_Tickで受信を処理し、do_Dance_Tickでダンスを進める。\n2. checkSensorsAndObstaclesで停止・回避を判断し、do_Drive_Tickでモーターへ出力する。\n3. do_Music_Tickで警告と音楽を更新する。\n4. IS_IRが真なら100μs、偽なら20μs待ち、次の周期へ進む。')
}

